export function loaderHtml(o: { bg: string; ink: string; mute: string; track: string; label: string }): string {
  return TEMPLATE.replace(/__BG__/g, o.bg)
    .replace(/__INK__/g, o.ink)
    .replace(/__MUTE__/g, o.mute)
    .replace(/__TRACK__/g, o.track)
    .replace(/__LABEL__/g, o.label);
}
